      users.set(String(payload.email).toLowerCase(), {
        password: payload.password,
        fullName: payload.fullName,
        gender: payload.gender,
      });
      res.writeHead(200, cors);
      return res.end(JSON.stringify({ message: "Patient registered." }));
    }

    if (req.url === "/api/Auth/login") {
      const user = users.get(String(payload.email || "").toLowerCase());
      if (!user || user.password !== payload.password) {
        res.writeHead(401, cors);
        return res.end(JSON.stringify({ title: "Invalid email or password." }));
