import { useCallback, useEffect, useMemo, useState } from 'react';
import { callAdmin } from '../../services/adminService.js';

// Loads one admin operation and reloads when its parameters change.
export default function useAdminQuery(method, params = {}) {
  const key = JSON.stringify(params);
  const [state, setState] = useState({ data: null, error: null });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let live = true;
    let request = 0;
    const args = [method, JSON.parse(key)];
    const run = async () => {
      const id = ++request;
      try {
        const data = await callAdmin(...args);
        if (live && id === request) setState({ data, error: null });
      } catch (error) {
        if (live && id === request) setState({ data: null, error });
      }
    };
    run();
    return () => { live = false; };
  }, [method, key, attempt]);

  return {
    data: state.data,
    error: state.error,
    loading: !state.data && !state.error,
    reload: useCallback(() => setAttempt(n => n + 1), []),
  };
}

// Search inputs re-query through this debounce so typing does not spam the API.
export function useDebouncedValue(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}
