// Admin helpers -------------------------------------------------------------
// The admin pages read one list shape everywhere: { items, total, filters }.
// Statuses arrive in any casing ("Pending", "APPROVED") and keys are lowercase.

const adminList = (body) => {
  const items = Array.isArray(body) ? body : (body?.items ?? body?.results ?? []);
  const total = Number(Array.isArray(body) ? items.length : (body?.total ?? body?.count ?? items?.length ?? 0));
  return {
    items: Array.isArray(items) ? items : [],
    total: Number.isFinite(total) ? total : 0,
    filters: (Array.isArray(body) ? null : body?.filters) || {},
  };
};

const lower = (value, fallback = '') => (value == null || value === '' ? fallback : String(value).toLowerCase());

const num = (value, fallback = 0) => {
  if (value == null || value === '') return fallback;
  const parsed = Number(String(value).replace(/,/g, ''));
  return Number.isFinite(parsed) ? parsed : fallback;
};

const pct = (value) => {
  if (value == null || value === '') return null;
  const parsed = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(parsed) ? parsed : null;
};
