// Keeps an optimistic status visible until the refetched row confirms it.
export function useStatusOverride(getStatus) {
  const [overrides, setOverrides] = useState({});
  const begin = (id, status) => setOverrides(prev => ({ ...prev, [id]: status }));
  const revert = (id) => setOverrides(prev => { const next = { ...prev }; delete next[id]; return next; });
  const reconcile = (rows) => setOverrides(prev => {
    let changed = false;
    const next = { ...prev };
    Object.entries(prev).forEach(([id, status]) => {
      if ((rows || []).find(row => row.id === id)?.status === status) { delete next[id]; changed = true; }
    });
    return changed ? next : prev;
  });
  return { overrides, begin, revert, reconcile };
}
```
